import json
import collections

demos = json.load(open("/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-7/play/users/u007/system/state/workspace/programs/task-026adbf3.json"))

print("Looking for: values that appear MINORITY (same count in same position in each part)\n")

for i, demo in enumerate(demos):
    inp = demo["input"]
    out = demo["output"]

    # Find separator
    sep = None
    if len(inp) > 0:
        for j in range(len(inp[0])):
            col = [inp[r][j] for r in range(len(inp))]
            if len(set(col)) == 1:
                sep = ('col', j, col[0])
                break

    if sep is None and len(inp) > 0:
        for i_row in range(len(inp)):
            row = inp[i_row]
            if len(set(row)) == 1:
                sep = ('row', i_row, row[0])
                break

    if sep is None:
        continue

    # Get actual background
    bg_counts = collections.Counter()
    for r in range(len(out)):
        for c in range(len(out[0])):
            if out[r][c] != 3:
                bg_counts[out[r][c]] += 1
    bg = bg_counts.most_common(1)[0][0] if bg_counts else None

    # Get parts
    if sep[0] == 'col':
        j = sep[1]
        left = [inp[r][:j] for r in range(len(inp))]
        right = [inp[r][j+1:] for r in range(len(inp))]
        assert len(left[0]) == len(right[0]), "Column split mismatch"

        for c in range(len(left[0])):
            column_left = [left[r][c] for r in range(len(left))]
            column_right = [right[r][c] for r in range(len(right))]
            if len(set(column_left)) == 1 and len(set(column_right)) == 1:
                left_val = column_left[0]
                right_val = column_right[0]
                if left_val != right_val:
                    print(f"Demo {i+1}: column {c}: left{left_val} != right{right_val}")

        # Get minority values (single-valued columns)
        left_cols = {}
        right_cols = {}
        for c in range(len(left[0])):
            column_left = [left[r][c] for r in range(len(left))]
            if len(set(column_left)) == 1:
                left_cols[c] = column_left[0]
        for c in range(len(right[0])):
            column_right = [right[r][c] for r in range(len(right))]
            if len(set(column_right)) == 1:
                right_cols[c] = column_right[0]

        print(f"Demo {i+1}: ")
        print(f"  Left majority columns: {left_cols}")
        print(f"  Right majority columns: {right_cols}")

        if left_cols and right_cols:
            matchings = [c for c in left_cols if c in right_cols and left_cols[c] == right_cols[c]]
            mismatches = [c for c in left_cols if c in right_cols and left_cols[c] != right_cols[c]]
            print(f"  Matching: {matchings}, Mismatching: {mismatches}")

        # Verify character positions in output
        print(f"  Expected bg={bg}")
        mismatches_in_output = [c for c in range(len(left[0])) if 
                                 c in left_cols and c in right_cols and 
                                 left_cols[c] != right_cols[c and bg_counts.get(c+out[r][c] == 3) else 1: -1]

        print(f"  Cells with value 3 in output: need check")
        cells_3 = [(r, c) for r in range(len(out)) for c in range(len(out[0])) if out[r][c] == 3]
        print(f"    Sample: {cells_3[:10]}")

    print()

