import json
import collections

demos = json.load(open("/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-7/play/users/u007/system/state/workspace/programs/task-026adbf3.json"))

def find_separator(grid):
    rows = len(grid)
    if rows == 0:
        return None
    for j in range(len(grid[0])):
        col = [grid[r][j] for r in range(rows)]
        if len(set(col)) == 1:
            return ('col', j, col[0])
    for i_row in range(rows):
        row = grid[i_row]
        if len(set(row)) == 1:
            return ('row', i_row, row[0])
    return None

print("Corrected analysis:\n")

for i, demo in enumerate(demos):
    inp = demo["input"]
    out = demo["output"]

    sep = find_separator(inp)
    if sep is None:
        print(f"Demo {i+1}: NO SEPARATOR FOUND")
        continue

    # Get parts
    if sep[0] == 'col':
        j = sep[1]
        left = [inp[r][:j] for r in range(len(inp))]
        right = [inp[r][j+1:] for r in range(len(inp))]
        left_count = collections.Counter(v for row in left for v in row)
        right_count = collections.Counter(v for row in right for v in row)
    else:
        i_row = sep[1]
        upper = inp[:i_row]
        lower = inp[i_row+1:]
        left_count = collections.Counter(v for row in upper for v in row)
        right_count = collections.Counter(v for row in lower for v in row)

    # Get actual background  
    bg_counts = collections.Counter()
    for r in range(len(out)):
        for c in range(len(out[0])):
            if out[r][c] != 3:
                bg_counts[out[r][c]] += 1
    bg = bg_counts.most_common(1)[0][0] if bg_counts else None

    print(f"Demo {i+1}: sep={sep[0]}{sep[1]}({sep[2]}), bg={bg}")

    if sep[0] == 'col':
        print(f"  Left: {len(left)}x{len(left[0])}, Right: {len(right)}x{len(right[0])}")
    else:
        print(f"  Upper: {len(upper)}x{len(upper[0])}, Lower: {len(lower)}x{len(lower[0])}")

    common = set(left_count.keys()) & set(right_count.keys())
    print(f"  Common values: {common}")

    # Key pattern value analysis
    if left_count and right_count:
        # The background is always the value that's common between parts
